#!/usr/bin/env bash
# Astra review 03: reproduce every SQL finding against the CURRENT migration 0007 (run before and after the fix).
cd "$(dirname "$0")/.."
KEEP=1 bash packages/db/scripts/test-migrations.sh >/dev/null 2>&1 || echo "(assertions failed; container kept)"
C=$(docker ps --format '{{.Names}}' | grep wos-migrations-test | head -1)
PSQL=(docker exec -i "$C" psql -q -t -A -U postgres -d wos -v ON_ERROR_STOP=1)
A=00000000-0000-0000-0000-00000000000a; B=00000000-0000-0000-0000-00000000000b; CA=00000000-0000-0000-0000-00000000000c; D=00000000-0000-0000-0000-00000000000d
ANY="(select id from wos.admin_actions where action = 'start_test_epochs' limit 1)"
run(){ local out; out=$(printf 'BEGIN;\n%s\nROLLBACK;\n' "$2" | "${PSQL[@]}" 2>&1 | grep -v '^$' | grep -v '^ok'); if grep -q '^ERROR' <<<"$out"; then echo "$1 => REJECTED: $(grep '^ERROR' <<<"$out" | head -1)"; else echo "$1 => $(tail -1 <<<"$out")"; fi; }
# dave: an account unrelated to everyone in the fixtures (committed; used by several repros)
"${PSQL[@]}" -c "insert into wos.accounts (id, handle, github_user_id, github_login, github_created_at, github_linked_at) values ('$D', 'dave', 1004, 'dave', now() - interval '400 days', now())" >/dev/null 2>&1
"${PSQL[@]}" -c "insert into wos.devices (id, account_id, name, client_kind, public_key) values ('00000000-0000-0000-0000-0000000000dd', '$D', 'mac', 'cli', repeat('A', 42) || 'M=')" >/dev/null 2>&1
DISPUTE_SETUP="set session_replication_role = replica;
insert into wos.epochs (epoch_number, mode, cluster, starts_at, ends_at, risk_review_hours, challenge_hours, policy_versions) values (6, 'test', 'devnet', now() - interval '10 days', now() - interval '3 days', 48, 48, '{}'), (7, 'test', 'devnet', now() - interval '10 days', now() - interval '3 days', 48, 48, '{}');
insert into wos.epoch_transitions (epoch_number, seq, from_state, to_state, actor, receipts_root, allocations_root, result_sha256, at) select e, 1, null, 'OPEN', 'system', null, null, null, now() - interval '10 days' from unnest(array[6,7]) e;
insert into wos.epoch_transitions (epoch_number, seq, from_state, to_state, actor, receipts_root, allocations_root, result_sha256, at) select e, 2, 'OPEN', 'CALCULATING', 'system', null, null, null, now() - interval '3 days' from unnest(array[6,7]) e;
insert into wos.epoch_transitions (epoch_number, seq, from_state, to_state, actor, receipts_root, allocations_root, result_sha256, at) select e, 3, 'CALCULATING', 'PROPOSED', 'system', 'sha256:' || repeat('1', 64), 'sha256:' || repeat('2', 64), 'sha256:' || repeat('3', 64), now() - interval '1 hour' from unnest(array[6,7]) e;
insert into wos.allocations (id, epoch_number, mode, account_id, beneficiary_kind, beneficiary_id, receipt_id, slice, pool_key, weight_micro, amount_base, explanation, explanation_sha256) values
 ('00000000-0000-0000-0000-0000000a6001', 6, 'test', '$A', 'person', '$A', null, 'completion_payout', 'p', 1, 100000000, '{}', 'sha256:' || repeat('1', 64)),
 ('00000000-0000-0000-0000-0000000a6002', 6, 'test', '$D', 'person', '$D', null, 'completion_payout', 'p', 1, 50000000, '{}', 'sha256:' || repeat('1', 64)),
 ('00000000-0000-0000-0000-0000000a7001', 7, 'test', '$A', 'person', '$A', null, 'completion_payout', 'p', 1, 100000000, '{}', 'sha256:' || repeat('1', 64)),
 ('00000000-0000-0000-0000-0000000a7002', 7, 'test', '$D', 'person', '$D', null, 'completion_payout', 'p', 1, 1000000, '{}', 'sha256:' || repeat('1', 64));
set session_replication_role = origin;"
DISPUTE_OPEN="insert into wos.allocation_disputes (id, epoch_number, disputer_account_id, stake_base, body) values ('00000000-0000-0000-0000-0000000d6001', 6, '$D', 1000000, '{\"items\": [{\"allocationId\": \"00000000-0000-0000-0000-0000000a6001\", \"reason\": \"inflated_usage\"}]}');
insert into wos.dispute_replies (allocation_id, account_id, body_untrusted) values ('00000000-0000-0000-0000-0000000a6001', '$A', 'the repair loops came from a flaky runner');
insert into wos.dispute_item_resolutions (allocation_id, outcome, admin_action_id, resulting_amount_base, excess_base, recovered_base) values ('00000000-0000-0000-0000-0000000a6001', 'CLIPPED', wos_test.aa('resolve_dispute', 'allocation', '00000000-0000-0000-0000-0000000a6001'), 60000000, 40000000, 40000000);"

echo "---- HIGH 1: entitlements not backed by allocations, maturity or settlement domain"
run "H1a two release_now rows for one reward" "insert into wos.entitlements (epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base) values (3, 'person', '$B', 'release_now', 150000000), (3, 'person', '$B', 'release_now', 150000000); select 'ACCEPTED: ' || count(*) || ' release_now rows with no allocation source' from wos.entitlements where kind = 'release_now' and epoch_number = 3;"
run "H1b holdback tranche matured in its own epoch" "insert into wos.entitlements (id, epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base) values ('00000000-0000-0000-0000-00000000e101', 3, 'person', '$B', 'holdback_tranche', 100000000); insert into wos.entitlements (epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base, source_tranche_id) values (3, 'person', '$B', 'holdback_matured', 100000000, '00000000-0000-0000-0000-00000000e101'); select 'ACCEPTED: tranche of epoch 3 matured in epoch 3';"
run "H1c devnet entitlement in a mainnet leaf" "insert into wos.wallet_bindings (account_id, cluster, wallet, kind, action, message, signature) values ('$B', 'mainnet-beta', repeat('5', 32), 'external', 'bind', '$B ' || repeat('5', 32), repeat('s', 88)); insert into wos.entitlements (id, epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base) values ('00000000-0000-0000-0000-00000000e102', 3, 'person', '$B', 'release_now', 5); insert into wos.claim_leaves (id, cluster, beneficiary_kind, beneficiary_id, wallet, amount_base, adapter_generation, leaf_sha256) values ('00000000-0000-0000-0000-0000000f1102', 'mainnet-beta', 'person', '$B', repeat('5', 32), 5, 1, 'sha256:' || repeat('5', 64)); insert into wos.entitlement_claims (entitlement_id, leaf_id) values ('00000000-0000-0000-0000-00000000e102', '00000000-0000-0000-0000-0000000f1102'); select 'ACCEPTED: devnet (test-epoch) entitlement attached to a mainnet-beta leaf';"

echo "---- HIGH 2: a paid entitlement paid again through another leaf"
run "H2a void a settled leaf with an unrelated action, re-claim, settle again" "insert into wos.leaf_voids (leaf_id, admin_action_id) values ('00000000-0000-0000-0000-0000000f1001', $ANY); insert into wos.entitlement_claims (entitlement_id, leaf_id) values ('00000000-0000-0000-0000-00000000e001', '00000000-0000-0000-0000-0000000f1002'); insert into wos.settlement_attempts (leaf_id, attempt, adapter_generation, signed_tx, signed_tx_sha256, signature, last_valid_block_height) values ('00000000-0000-0000-0000-0000000f1002', 1, 1, '\x0a', 'sha256:' || repeat('a', 64), 'sig-r2a-' || repeat('b', 40), 500); insert into wos.settlement_outcomes (leaf_id, attempt, outcome, commitment, history_checked, slot) values ('00000000-0000-0000-0000-0000000f1002', 1, 'confirmed', 'finalized', true, 999); select 'ACCEPTED: entitlement e001 confirmed in ' || count(*) || ' leaves' from wos.settlement_outcomes o join wos.entitlement_claims x on x.leaf_id = o.leaf_id where x.entitlement_id = '00000000-0000-0000-0000-00000000e001' and o.outcome = 'confirmed';"

echo "---- HIGH 3: appeals do not determine settlement; stakes not reserved"
run "H3a reversed appeal still settles 40 excess and a bounty" "$DISPUTE_SETUP $DISPUTE_OPEN insert into wos.dispute_appeals (allocation_id, appellant_account_id, statement_untrusted) values ('00000000-0000-0000-0000-0000000a6001', '$A', 'the usage was legitimate: flaky WebKit CI'); insert into wos.dispute_appeal_decisions (allocation_id, decision, final_amount_base, admin_action_id) values ('00000000-0000-0000-0000-0000000a6001', 'reversed', 100000000, wos_test.aa('decide_appeal', 'allocation', '00000000-0000-0000-0000-0000000a6001')); insert into wos.dispute_settlements (dispute_id, total_excess_base, recovered_base, bounty_base, stake_forfeited_base, settled_in_epoch) values ('00000000-0000-0000-0000-0000000d6001', 40000000, 40000000, 8000000, 0, 6); select 'ACCEPTED: appeal reversed to 100 but settlement derived excess 40, bounty 8, no stake forfeited';"
run "H3b settle before the appeal window, then appeal" "$DISPUTE_SETUP $DISPUTE_OPEN insert into wos.dispute_settlements (dispute_id, total_excess_base, recovered_base, bounty_base, stake_forfeited_base, settled_in_epoch) values ('00000000-0000-0000-0000-0000000d6001', 40000000, 40000000, 8000000, 0, 6); insert into wos.dispute_appeals (allocation_id, appellant_account_id, statement_untrusted) values ('00000000-0000-0000-0000-0000000a6001', '$A', 'appeal filed after the settlement was written'); select 'ACCEPTED: settled immediately, timely appeal filed against an immutable settlement';"
run "H3c three disputes staking the same 1 WOS" "$DISPUTE_SETUP insert into wos.allocation_disputes (epoch_number, disputer_account_id, stake_base, body) select 7, '$D', 1000000, '{\"items\": [{\"allocationId\": \"00000000-0000-0000-0000-0000000a7001\", \"reason\": \"other\"}]}' from generate_series(1, 3); select 'ACCEPTED: ' || sum(stake_base) || ' staked against a pending balance of 1000000' from wos.allocation_disputes where epoch_number = 7;"

echo "---- HIGH 4: confiscation skips due process; partial recovery mishandled"
CONF="insert into wos.confiscations (id, beneficiary_kind, beneficiary_id, proven_excess_base, finding_ref, admin_action_id, reply_closes_at, appeal_closes_at) values ('00000000-0000-0000-0000-0000000c0f04', 'person', '$B', 10000000, 'pattern finding', wos_test.aa('confiscate', 'confiscation', '00000000-0000-0000-0000-0000000c0f04'), now() + interval '73 hours', now() + interval '242 hours');
insert into wos.confiscation_appeal_decisions (confiscation_id, decision, admin_action_id) values ('00000000-0000-0000-0000-0000000c0f04', 'upheld', $ANY);"
run "H4a upheld immediately with an unrelated action, then seized" "insert into wos.entitlements (id, epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base) values ('00000000-0000-0000-0000-00000000e104', 3, 'person', '$B', 'release_now', 100000000); $CONF insert into wos.confiscation_sources (confiscation_id, source_kind, source_id, amount_base) values ('00000000-0000-0000-0000-0000000c0f04', 'unclaimed_entitlement', '00000000-0000-0000-0000-00000000e104', 10000000); select 'ACCEPTED: seized at notice time, both windows skipped';"
run "H4b the remaining 90 of a partly confiscated entitlement is unclaimable" "insert into wos.entitlements (id, epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base) values ('00000000-0000-0000-0000-00000000e104', 3, 'person', '$B', 'release_now', 100000000); $CONF insert into wos.confiscation_sources (confiscation_id, source_kind, source_id, amount_base) values ('00000000-0000-0000-0000-0000000c0f04', 'unclaimed_entitlement', '00000000-0000-0000-0000-00000000e104', 10000000); insert into wos.claim_leaves (id, cluster, beneficiary_kind, beneficiary_id, wallet, amount_base, adapter_generation, leaf_sha256) values ('00000000-0000-0000-0000-0000000f1104', 'devnet', 'person', '$B', repeat('3', 32), 90000000, 1, 'sha256:' || repeat('6', 64)); insert into wos.entitlement_claims (entitlement_id, leaf_id) values ('00000000-0000-0000-0000-00000000e104', '00000000-0000-0000-0000-0000000f1104'); select 'claim of the remaining 90 accepted';"
run "H4c tranche 100, confiscate 10, mature 100" "insert into wos.entitlements (id, epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base) values ('00000000-0000-0000-0000-00000000e105', 3, 'person', '$B', 'holdback_tranche', 100000000); $CONF insert into wos.confiscation_sources (confiscation_id, source_kind, source_id, amount_base) values ('00000000-0000-0000-0000-0000000c0f04', 'holdback', '00000000-0000-0000-0000-00000000e105', 10000000); insert into wos.entitlements (epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base, source_tranche_id) values (3, 'person', '$B', 'holdback_matured', 100000000, '00000000-0000-0000-0000-00000000e105'); select 'ACCEPTED: 10 confiscated and 100 matured from a 100 tranche';"

echo "---- HIGH 5: qualification accepts assertions"
run "H5a empty-evidence qualification, arbitrary revision, usage reused by a second receipt" "insert into wos.qualification_results (subject_kind, subject_id, subject_revision, lease_id, lease_generation, passed, snapshot_sha256s, evidence) values ('document', '00000000-0000-0000-0000-0000000000d1', 'any-revision', '00000000-0000-0000-0000-0000000000c1', 1, true, '{}', '{}'); insert into wos.work_dedup_keys (dedup_key, source) values ('work:r5a', 'receipt'); select wos_test.receipt(gen_random_uuid(), '$B', 'APPLICATION_ROADMAP', 'planning', 'attested_usage', 12000, 12000, 'ATTESTED', '{00000000-0000-0000-0000-0000000ad001}', '00000000-0000-0000-0000-0000000fa001', 'document', '00000000-0000-0000-0000-0000000000d1', '00000000-0000-0000-0000-0000000000c1', 1, 'work:r5a', 2); select 'ACCEPTED: usage receipt ad001 now backs ' || count(*) || ' contributions' from wos.contribution_receipts where usage_receipt_ids @> '{00000000-0000-0000-0000-0000000ad001}';"

echo "---- HIGH 6: audit verdicts not bound to assignment, packet or provider"
AUDIT_SETUP="set session_replication_role = replica;
insert into wos.tasks (id, kind, state, role, created_at) values ('00000000-0000-0000-0000-0000000006f1', 'payout_audit', 'leased', 'payout_auditor', now());
insert into wos.leases (id, task_id, account_id, device_id, state, context_plan, expires_at, hard_deadline_at, generation) values ('00000000-0000-0000-0000-0000000006c1', '00000000-0000-0000-0000-0000000006f1', '$D', '00000000-0000-0000-0000-0000000000dd', 'active', '{}', now() + interval '30 minutes', now() + interval '3 hours', 1);
insert into wos.agent_runs (id, lease_id, manifest_id, account_id, device_id, record, signature_valid) values ('00000000-0000-0000-0000-0000000006a1', '00000000-0000-0000-0000-0000000006c1', '00000000-0000-0000-0000-0000000000a1', '$D', '00000000-0000-0000-0000-0000000000dd', '{\"provider\": \"claude_cli\"}', true);
set session_replication_role = origin;
insert into wos.payout_audit_quorums (id, receipt_id, purpose, size, review_policy_version) values ('00000000-0000-0000-0000-0000000ae601', '00000000-0000-0000-0000-0000000cc002', 'sampled', 2, 'review-policy.v1'), ('00000000-0000-0000-0000-0000000ae602', '00000000-0000-0000-0000-0000000cc002', 'dispute_gate', 2, 'review-policy.v1');"
run "H6a one claude run submitted as a codex verdict to two unrelated quorums" "$AUDIT_SETUP insert into wos.payout_audit_verdicts (quorum_id, slot, outside_feature, packet_id, reviewer_account_id, task_id, lease_id, agent_run_id, provider, judgment, body, verdict_sha256) select q, 1, true, gen_random_uuid(), '$D', '00000000-0000-0000-0000-0000000006f1', '00000000-0000-0000-0000-0000000006c1', '00000000-0000-0000-0000-0000000006a1', 'codex_cli', 'plausible', '{}', 'sha256:' || md5(q::text) || md5(q::text) from unnest(array['00000000-0000-0000-0000-0000000ae601', '00000000-0000-0000-0000-0000000ae602']::uuid[]) q; select 'ACCEPTED: one run, no assignment, declared codex_cli, used in ' || count(*) || ' quorums' from wos.payout_audit_verdicts where agent_run_id = '00000000-0000-0000-0000-0000000006a1';"

echo "---- HIGH 7: authorization does not bind the exact operation"
run "H7a one record_offset action reused for two offsets of different amounts" "select set_config('r.aid', wos_test.aa('record_offset', 'beneficiary', '$B')::text, true); insert into wos.offsets (beneficiary_kind, beneficiary_id, amount_base, admin_action_id) values ('person', '$B', 1, current_setting('r.aid')::uuid), ('person', '$B', 999999999, current_setting('r.aid')::uuid); select 'ACCEPTED: 2 offsets from one action';"
run "H7b revoke with a one-person resolve_dispute action and no resolution" "insert into wos.receipt_status_events (receipt_id, from_status, to_status, kind, admin_action_id) values ('00000000-0000-0000-0000-0000000cc002', 'ACTIVE', 'REVOKED', 'revoked', wos_test.aa('resolve_dispute', 'receipt', '00000000-0000-0000-0000-0000000cc002')); select 'ACCEPTED: receipt revoked by one maintainer without any dispute resolution';"
run "H7c confiscation appeal decided with any action" "$CONF select 'ACCEPTED: upheld with start_test_epochs';"

echo "---- HIGH 9: settlement finality"
LEAF9="insert into wos.entitlements (id, epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base) values ('00000000-0000-0000-0000-00000000e109', 3, 'person', '$B', 'release_now', 7); insert into wos.claim_leaves (id, cluster, beneficiary_kind, beneficiary_id, wallet, amount_base, adapter_generation, leaf_sha256) values ('00000000-0000-0000-0000-0000000f1109', 'devnet', 'person', '$B', repeat('3', 32), 7, 1, 'sha256:' || repeat('9', 64)); insert into wos.entitlement_claims (entitlement_id, leaf_id) values ('00000000-0000-0000-0000-00000000e109', '00000000-0000-0000-0000-0000000f1109'); insert into wos.settlement_attempts (leaf_id, attempt, adapter_generation, signed_tx, signed_tx_sha256, signature, last_valid_block_height) values ('00000000-0000-0000-0000-0000000f1109', 1, 1, '\x09', 'sha256:' || repeat('9', 64), 'sig-r9-1', 900);"
run "H9a confirmed with NULL commitment" "$LEAF9 insert into wos.settlement_outcomes (leaf_id, attempt, outcome) values ('00000000-0000-0000-0000-0000000f1109', 1, 'confirmed'); select 'ACCEPTED: confirmed outcome with commitment ' || coalesce(commitment, 'NULL') from wos.settlement_outcomes where leaf_id = '00000000-0000-0000-0000-0000000f1109';"
run "H9c failed_before_broadcast of signed bytes, then a second signed attempt" "$LEAF9 insert into wos.settlement_outcomes (leaf_id, attempt, outcome) values ('00000000-0000-0000-0000-0000000f1109', 1, 'failed_before_broadcast'); insert into wos.settlement_attempts (leaf_id, attempt, adapter_generation, signed_tx, signed_tx_sha256, signature, last_valid_block_height) values ('00000000-0000-0000-0000-0000000f1109', 2, 1, '\x0b', 'sha256:' || repeat('b', 64), 'sig-r9-2', 950); select 'ACCEPTED: two signed transactions for one leaf, the first never proven expired';"

echo "---- MEDIUM 12: Genesis reference population not frozen"
GEN_SETUP="set session_replication_role = replica;
insert into wos.work_dedup_keys (dedup_key, source) values ('work:dave#1', 'receipt');
insert into wos.contribution_receipts (id, account_id, contribution_type, slice, evidence_class, acceptance_event, independence, initial_status, weight_micro, attested_acu_micro, cap_acu_micro, lowest_verification, subject_kind, subject_id, dedup_key, admitted_epoch, body, receipt_sha256, qualified_at) values ('00000000-0000-0000-0000-0000000cc0d1', '$D', 'PROPOSAL', 'outcomes', 'outcome', 'x', 'independent', 'ACTIVE', 1, 0, 1, 'ATTESTED', 'proposal', gen_random_uuid(), 'work:dave#1', 2, '{}', 'sha256:' || repeat('d', 64), now());
set session_replication_role = origin;"
run "M12a reference receipt approved, then its account added as a Genesis beneficiary" "$GEN_SETUP insert into wos.genesis_reference_receipts (receipt_id, admin_action_id) values ('00000000-0000-0000-0000-0000000cc0d1', wos_test.aa('approve_genesis_reference', 'genesis_reference', 'v1')); insert into wos.work_dedup_keys (dedup_key, source) values ('work:gen:dave', 'genesis'); insert into wos.genesis_contributions (contributor_account_id, evidence_kind, evidence_refs, evidence_sha256, dedup_key, size_points, genesis_policy_version, body) values ('$D', 'retro_abu', '{waronsaas/wos@def}', 'sha256:' || repeat('e', 64), 'work:gen:dave', 3, 'genesis-policy.v1', '{}'); select 'ACCEPTED: dave is both in the reference population and a Genesis beneficiary';"
run "M12b overlapping commit evidence under two keys, no commit claims" "insert into wos.work_dedup_keys (dedup_key, source) values ('work:gen:x1', 'genesis'), ('work:gen:x2', 'genesis'); insert into wos.genesis_contributions (contributor_account_id, evidence_kind, evidence_refs, evidence_sha256, dedup_key, size_points, genesis_policy_version, body) values ('$CA', 'git_commit', array[repeat('2', 40)], 'sha256:' || repeat('e', 64), 'work:gen:x1', 3, 'genesis-policy.v1', '{}'), ('$CA', 'git_commit', array[repeat('2', 40)], 'sha256:' || repeat('e', 64), 'work:gen:x2', 3, 'genesis-policy.v1', '{}'); select 'ACCEPTED: one commit credited under two retro keys';"

echo "---- review-02 residuals named in review 03"
run "M17 wallet bound without the publication disclosure" "insert into wos.wallet_bindings (account_id, cluster, wallet, kind, action, message, signature) values ('$CA', 'devnet', repeat('6', 32), 'external', 'bind', '$CA ' || repeat('6', 32), repeat('s', 88)); select 'ACCEPTED: carol bound a wallet without consent';"

echo "---- concurrency (two sessions; fixtures committed in the throwaway container)"
"${PSQL[@]}" >/dev/null 2>&1 <<SQL
insert into wos.entitlements (id, epoch_number, beneficiary_kind, beneficiary_id, kind, amount_base) values
 ('00000000-0000-0000-0000-00000000e201', 3, 'person', '$B', 'release_now', 10), ('00000000-0000-0000-0000-00000000e202', 3, 'person', '$B', 'release_now', 50000000),
 ('00000000-0000-0000-0000-00000000e203', 3, 'person', '$B', 'release_now', 50000000), ('00000000-0000-0000-0000-00000000e204', 3, 'person', '$B', 'release_now', 11);
insert into wos.claim_leaves (id, cluster, beneficiary_kind, beneficiary_id, wallet, amount_base, adapter_generation, leaf_sha256) values
 ('00000000-0000-0000-0000-0000000f1201', 'devnet', 'person', '$B', repeat('3', 32), 10, 1, 'sha256:' || repeat('1', 64)),
 ('00000000-0000-0000-0000-0000000f1202', 'devnet', 'person', '$B', repeat('3', 32), 10, 1, 'sha256:' || repeat('2', 64)),
 ('00000000-0000-0000-0000-0000000f1204', 'devnet', 'person', '$B', repeat('3', 32), 11, 1, 'sha256:' || repeat('4', 64));
insert into wos.entitlement_claims (entitlement_id, leaf_id) values ('00000000-0000-0000-0000-00000000e204', '00000000-0000-0000-0000-0000000f1204');
insert into wos.confiscations (id, beneficiary_kind, beneficiary_id, proven_excess_base, finding_ref, admin_action_id, reply_closes_at, appeal_closes_at) values ('00000000-0000-0000-0000-0000000c0f05', 'person', '$B', 60000000, 'finding', wos_test.aa('confiscate', 'confiscation', '00000000-0000-0000-0000-0000000c0f05'), now() + interval '73 hours', now() + interval '242 hours');
insert into wos.confiscation_appeal_decisions (confiscation_id, decision, admin_action_id) values ('00000000-0000-0000-0000-0000000c0f05', 'upheld', $ANY);
insert into wos.duty_events (offer_id, seq, account_id, epoch_number, kind, deadline_at) values ('00000000-0000-0000-0000-0000000d0002', 1, '$B', 3, 'offered', now() + interval '1 day');
SQL
two(){ # $1 label, $2 first session (held open 3 s), $3 second session, $4 verdict query
  printf 'BEGIN;\n%s\nselect pg_sleep(3);\nCOMMIT;\n' "$2" | "${PSQL[@]}" >/tmp/r03-s1.$$ 2>&1 &
  sleep 1
  printf '%s\n' "$3" | "${PSQL[@]}" >/tmp/r03-s2.$$ 2>&1
  wait
  echo "$1 => s1: $(grep -v '^$' /tmp/r03-s1.$$ | tail -1) | s2: $(grep -v '^$' /tmp/r03-s2.$$ | tail -1) | $(printf '%s\n' "$4" | "${PSQL[@]}" 2>&1 | tail -1)"
}
two "H2b one entitlement attached to two leaves concurrently" \
  "insert into wos.entitlement_claims (entitlement_id, leaf_id) values ('00000000-0000-0000-0000-00000000e201', '00000000-0000-0000-0000-0000000f1201');" \
  "insert into wos.entitlement_claims (entitlement_id, leaf_id) values ('00000000-0000-0000-0000-00000000e201', '00000000-0000-0000-0000-0000000f1202');" \
  "select case when count(*) > 1 then 'ACCEPTED: e201 in ' || count(*) || ' live leaves' else 'rejected' end from wos.entitlement_claims where entitlement_id = '00000000-0000-0000-0000-00000000e201';"
two "H4d two 50 sources against 60 proven excess concurrently" \
  "insert into wos.confiscation_sources (confiscation_id, source_kind, source_id, amount_base) values ('00000000-0000-0000-0000-0000000c0f05', 'unclaimed_entitlement', '00000000-0000-0000-0000-00000000e202', 50000000);" \
  "insert into wos.confiscation_sources (confiscation_id, source_kind, source_id, amount_base) values ('00000000-0000-0000-0000-0000000c0f05', 'unclaimed_entitlement', '00000000-0000-0000-0000-00000000e203', 50000000);" \
